def evaluate(
    current_reputation: float,
    observation: dict,
    my_history: list[dict],
    round_num: int
) -> float:
    # Strict: heavily penalize defection, small reward for donation
    if observation['action'] == 'donate':
        return min(0.8, current_reputation + 0.1)
    else:
        return max(-1.0, current_reputation - 0.5)

def decide(
    recipient_reputation: float,
    round_num: int,
    my_history: list[dict]
) -> bool:
    # Only donate if reputation is very high
    return recipient_reputation >= 0.8

